public class Acceptance {static void eq(Object actual,Object expected){if(!actual.equals(expected))throw new AssertionError("expected "+expected+" got "+actual);} public static void main(String[] args){Task t=new Task();eq(t.transition("CLOSED"),false);eq(t.state(),"NEW");eq(t.attempts(),0);eq(t.transition("RUNNING"),true);eq(t.attempts(),1);eq(t.transition("RECOVERY_REQUIRED"),true);eq(t.transition("RUNNING"),false);eq(t.state(),"RECOVERY_REQUIRED");eq(t.transition("RECOVERED"),true);eq(t.transition("RUNNING"),true);} }
